with ins as (insert into public.artist_sound_tags (artist_slug,tag,source_url) select x.s,x.tag,x.u from json_to_recordset('[{"s":"prismer","tag":"thumping bass, breaks and techno","u":"https://www.youtube.com/watch?v=28cFJOVcjc8"},{"s":"prismer","tag":"deep, boundaryless realm of sound","u":"https://theindianmusicdiaries.com/electrifying-nights-await-g5as-port-after-dark-with-dj-nariki-prismer/"},{"s":"prismer","tag":"dark and arresting sets","u":"https://www.thewildcity.com/mixes/6930-wild-city-148-rohan-kal"},{"s":"dj-pants","tag":"downtempo breakbeats and deep basslines","u":"https://www.thewildcity.com/mixes/20911-wild-city-242-dj-pants"},{"s":"spiralynk","tag":"organised chaos","u":"https://www.mixcloud.com/aubele/techno-quarantuned-feat-spiralynk-episode-5/"},{"s":"spiralynk","tag":"harsh noise and sine tones","u":"https://spiralynk.bandcamp.com/track/sinetific-noise"},{"s":"spiralynk","tag":"liquid and elastic","u":"https://antarikshrecords.bandcamp.com/album/liminal-rift-ep"},{"s":"mogasu","tag":"no fixed style, drawing on a wide world of music","u":"https://dgtl-festival.com/en/artists/mogasu/"},{"s":"mogasu","tag":"exploring diverse tunes","u":"https://www.youtube.com/watch?v=fvFuK5sQFDs"},{"s":"bawra","tag":"percussive and subtle techno","u":"https://soundcloud.com/thewildcity/wild-city-264-baawra"},{"s":"bawra","tag":"atmospheric electronic sound","u":"https://dgtl-festival.com/en/artists/baawra"},{"s":"thegreybox","tag":"hip-hop, soul, R&B and house","u":"https://www.thewildcity.com/events/14736-wild-city-presents-listening-sessions-thegreybox"},{"s":"thegreybox","tag":"understated, muted banger with a sombre haze of melancholia","u":"https://www.thewildcity.com/features/15432-wild-city-singled-out-september-2019"}]'::json) as x(s text,tag text,u text) join public.artists a on a.slug=x.s on conflict (artist_slug,tag) do nothing returning 1) select count(*) from ins;